-- SUPABASE POSTGRESQL MIGRATION FOR LAB BIOLOGI SMANSA PINRANG

DROP TABLE IF EXISTS log_riwayat CASCADE;
DROP TABLE IF EXISTS peminjaman CASCADE;
DROP TABLE IF EXISTS barang CASCADE;
DROP TABLE IF EXISTS admin CASCADE;


CREATE TABLE admin (
  id BIGSERIAL PRIMARY KEY,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  nama_lengkap TEXT NOT NULL,
  nip TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE barang (
  id BIGSERIAL PRIMARY KEY,
  kode_barang TEXT,
  nama_barang TEXT NOT NULL,
  spesifikasi TEXT,
  kategori TEXT NOT NULL,
  sub_kategori TEXT,
  stok_total INTEGER NOT NULL DEFAULT 0,
  stok_tersedia INTEGER NOT NULL DEFAULT 0,
  stok_rusak INTEGER NOT NULL DEFAULT 0,
  satuan TEXT DEFAULT 'Buah',
  kondisi TEXT DEFAULT 'Baik',
  lokasi_penyimpanan TEXT,
  sumber_dana TEXT,
  keterangan TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE peminjaman (
  id BIGSERIAL PRIMARY KEY,
  nomor_formulir TEXT,
  barang_id BIGINT NOT NULL,
  nama_peminjam TEXT NOT NULL,
  kelas_jabatan TEXT,
  keperluan TEXT,
  jumlah INTEGER NOT NULL,
  tanggal_pinjam DATE NOT NULL,
  tanggal_rencana_kembali DATE,
  tanggal_kembali_aktual DATE,
  kondisi_saat_pinjam TEXT DEFAULT 'Baik',
  kondisi_saat_kembali TEXT,
  status TEXT NOT NULL DEFAULT 'dipinjam',
  keterangan TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE log_riwayat (
  id BIGSERIAL PRIMARY KEY,
  jenis_aktivitas TEXT NOT NULL,
  barang_id BIGINT,
  peminjaman_id BIGINT,
  deskripsi TEXT NOT NULL,
  admin_name TEXT NOT NULL,
  waktu TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_barang_kategori ON barang(kategori);
CREATE INDEX idx_barang_nama ON barang(nama_barang);
CREATE INDEX idx_peminjaman_status ON peminjaman(status);
CREATE INDEX idx_log_waktu ON log_riwayat(waktu DESC);

SELECT setval('barang_id_seq', (SELECT MAX(id) FROM barang));

SELECT setval('peminjaman_id_seq', (SELECT MAX(id) FROM peminjaman));

SELECT setval('log_riwayat_id_seq', (SELECT MAX(id) FROM log_riwayat));

